/* From Uiverse.io by JkHuger - Source: I've seen on a website and i recreated it but i don't remember. - Tags: animation, music, rhythm */
.__UIV_SCOPE__ .wave-menu {
  border: 4px solid #545FE5;
  border-radius: 50px;
  width: 200px;
  height: 45px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 0;
  margin: 0;
  cursor: pointer;
  transition: ease 0.2s;
  position: relative;
  background: #fff;
}

.__UIV_SCOPE__ .wave-menu li {
  list-style: none;
  height: 30px;
  width: 4px;
  border-radius: 10px;
  background: #545FE5;
  margin: 0 6px;
  padding: 0;
  animation-name: wave1;
  animation-duration: 0.3s;
  animation-iteration-count: infinite;
  animation-direction: alternate;
  transition: ease 0.2s;
}

.__UIV_SCOPE__ .wave-menu:hover > li {
  background: #fff;
}

.__UIV_SCOPE__ .wave-menu:hover {
  background: #545FE5;
}

.__UIV_SCOPE__ .wave-menu li:nth-child(2) {
  animation-name: wave2;
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .wave-menu li:nth-child(3) {
  animation-name: wave3;
  animation-delay: 0.23s;
  animation-duration: 0.4s;
}

.__UIV_SCOPE__ .wave-menu li:nth-child(4) {
  animation-name: wave4;
  animation-delay: 0.1s;
  animation-duration: 0.3s;
}

.__UIV_SCOPE__ .wave-menu li:nth-child(5) {
  animation-delay: 0.5s;
}

.__UIV_SCOPE__ .wave-menu li:nth-child(6) {
  animation-name: wave2;
  animation-duration: 0.5s;
}

.__UIV_SCOPE__ .wave-menu li:nth-child(8) {
  animation-name: wave4;
  animation-delay: 0.4s;
  animation-duration: 0.25s;
}

.__UIV_SCOPE__ .wave-menu li:nth-child(9) {
  animation-name: wave3;
  animation-delay: 0.15s;
}

@keyframes wave1 {
  from {
    transform: scaleY(1);
  }

  to {
    transform: scaleY(0.5);
  }
}

@keyframes wave2 {
  from {
    transform: scaleY(0.3);
  }

  to {
    transform: scaleY(0.6);
  }
}

@keyframes wave3 {
  from {
    transform: scaleY(0.6);
  }

  to {
    transform: scaleY(0.8);
  }
}

@keyframes wave4 {
  from {
    transform: scaleY(0.2);
  }

  to {
    transform: scaleY(0.5);
  }
}
